	this.next_btn_anime.parent = this;
	this.next_btn_anime.setTransform(986.9,684.7,1.67,1.67);

	this.back_btn = new lib.back_btn();
	this.back_btn.parent = this;
	this.back_btn.setTransform(92.1,731.7,1,1.001,180,0,0,0.1,0.1);
	new cjs.ButtonHelper(this.back_btn, 0, 1, 2);

	this.next_btn = new lib.arrow_btncolor();
	this.next_btn.parent = this;
	this.next_btn.setTransform(991.6,680.9,2.004,2.006);
	new cjs.ButtonHelper(this.next_btn, 0, 1, 2);

	this.timeline.addTween(cjs.Tween.get({}).to({state:[]}).to({state:[{t:this.next_btn},{t:this.back_btn},{t:this.next_btn_anime}]},1).wait(1));

	// Layer 5
	this.mobileStart_btn = new lib.MobileStart();
	this.mobileStart_btn.parent = this;
	this.mobileStart_btn.setTransform(550,384);
	this.mobileStart_btn.alpha = 0.012;
	new cjs.ButtonHelper(this.mobileStart_btn, 0, 1, 1);

	this.timeline.addTween(cjs.Tween.get(this.mobileStart_btn).to({_off:true},1).wait(1));

	// masktop
	this.shape = new cjs.Shape();
	this.shape.graphics.f().s("#FFFFFF").ss(3,1,1).p("EhFogtlMCLRAAAQDwAACpCpQCqCqAADvMAAABJHQAADviqCqQipCpjwAAMiLRAAAQjwAAiqipQipiqAAjvMAAAhJHQAAjvCpiqQCqipDwAAg");
	this.shape.setTransform(550,307.8);

	this.timeline.addTween(cjs.Tween.get(this.shape).wait(2));

	// mask (mask)
	var mask = new cjs.Shape();
	mask._off = true;
	mask.graphics.p("EhFoAtmQjwAAipipQiqiqAAjvMAAAhJHQAAjvCqiqQCpipDwAAMCLRAAAQDvAACqCpQCpCqAADvMAAABJHQAADvipCqQiqCpjvAAg");
	mask.setTransform(550,307.8);

